"use strict";(globalThis.webpackChunkgrc||=[]).push([[81212],{74063(e){e.exports=JSON.parse('{"citeKey":"gainaru2024deriveor","slug":"gainaru-2024-derive-or-4aad","title":"To Derive or Not to Derive: I/O Libraries Take Charge of Derived Quantities Computation","authors":["A. Gainaru","G. Eisenhauer","N. Podhorszki","L. Dulac","Q. Gong","A. Kougkas","J. Lofstead","X.-H. Sun","S. Klasky"],"venue":"IEEE/SBC 36th International Symposium on Computer Architecture and High Performance Computing (SBAC-PAD 2024), Hawaii, USA","type":"Conference","entryType":"inproceedings","date":"November, 2024","year":2024,"era":"iit","month":11,"doi":"10.1109/sbac-pad63648.2024.00030","abstract":"The ever-increasing volume of data produced by HPC simulations necessitates scalable methods for data explo- ration and knowledge extraction. Scientific data analysis often in- volves complex queries across distributed datasets, requiring ma- nipulation of multiple primary variables and generating derived data that needs to be handled efficiently, creating challenges for applications that need to parse many large datasets. Relying on individual applications to handle all intermediate data generally leads to redundant computations across studies and unnecessary data transfers. In this paper, we investigate the performance of different approaches where applications define derived variables as quantities of interest (QoIs) and offload the computation and transfer of these QoIs to the I/O library. This significantly reduces redundancy and optimizes data movement across the distributed storage and processing infrastructure by allowing control over when and where derived variables are computed. We present a detailed analysis of the performance-storage trade-offs associated with different solutions and showcase results for our study on two large-scale datasets created from climate and combustion simulations.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2024/gainaru-2024-derive-or-4aad.pdf"},"tags":["HPC Analysis","Large-Scale I/O","Derived Variables","Quantities of Interest"],"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["coeus"],"memberAuthors":["gainaru-ana","kougkas-anthony","lofstead-jay","sun-xian-he","klasky-scott"]}')}}]);